Q: How to solve `npm i package` and Vscode Default Formatter conflict A: <p>Using</p>
<pre><code>&quot;[json]&quot;: {

&quot;files.insertFinalNewLine&quot;:true

}
</code></pre>
<p>helps for most of the cases</p>

Q: Global.Application_PostAcquireRequestState Session state is not available in this context when missing page 404 A: <p>The solution is to use <code>Context?.Session</code> instead of <code>Session</code> like this</p>
<pre><code>protected void Application_PostAcquireRequestState(object sender, EventArgs e)
{
    if (Context?.Request == null)
        return;
    if (!Context.Response.IsClientConnected) return;
    try
    {
        if (Context?.Session == null)
            return;

        if (string.IsNullOrWhiteSpace((string)Context.Session[&quot;checkval&quot;]))
        {
            Context.Session[&quot;checkval&quot;] = Context.Request.Headers[&quot;checkval&quot;];
        }
        else
        {
            Debug.WriteLine(Context.Session[&quot;checkval&quot;]);
        }
    }
    catch (ThreadAbortException ex) { throw ex; }
    catch (Exception ex)
    {
        cError oError = cError.RecordError(ex, &quot;Global.Application_PostAcquireRequestState&quot;, Context);
        return;
    }
}
</code></pre>
